  const date = (n=0) => { const d=new Date(); d.setDate(d.getDate()+n); return d.toISOString().slice(0,10); };
  const safe = v => String(v ?? '').replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const moneylessDate = v => v ? new Date(v+'T00:00:00').toLocaleDateString('id-ID',{day:'numeric',month:'short',year:'numeric'}) : '—';
  const initials = v => String(v||'OI').trim().split(/\s+/).slice(0,2).map(x=>x[0]).join('').toUpperCase();
  const seed = () => {
    const demo={users:[{id:'user_demo',name:'Kirana Ayu',email:'demo@orginventory.id',password:'demo123',phone:'0812 3456 7890'}],session:null,activeOrg:'org_komunitas',orgs:[
      {id:'org_komunitas',name:'Peralatan Raka',description:'Peralatan pribadi untuk dipinjam teman dan lingkungan kampus.',location:'Jakarta Selatan',visibility:'public',createdAt:date(-170)},
      {id:'org_kampus',name:'Himpunan Mahasiswa Informatika',description:'Ruang Inventaris mahasiswa dan kegiatan teknologi kampus.',location:'Depok, Jawa Barat',visibility:'public',createdAt:date(-120)},
      {id:'org_foto',name:'Klub Fotografi Kita',description:'Berbagi peralatan dan belajar fotografi bersama.',location:'Bekasi, Jawa Barat',visibility:'public',createdAt:date(-80)}
    ],memberships:[{id:'mem_demo_owner',orgId:'org_komunitas',userId:'user_demo',role:'ADMIN',status:'active'},{id:'mem_demo_admin',orgId:'org_kampus',userId:'user_demo',role:'ADMIN',status:'active'},{id:'mem_demo_member',orgId:'org_foto',userId:'user_demo',role:'MEMBER',status:'active'}],assets:[
      {id:'asset_cam',orgId:'org_foto',name:'Kamera Mirrorless Sony',code:'CAM-001',category:'Kamera',location:'Lemari A-01',condition:'Baik',status:'available',qty:1,description:'Kamera mirrorless untuk dokumentasi kegiatan.',icon:'📷'},
      {id:'asset_tripod',orgId:'org_foto',name:'Tripod Aluminium',code:'ACC-014',category:'Aksesori',location:'Lemari A-02',condition:'Baik',status:'available',qty:1,description:'Tripod aluminium adjustable.',icon:'🦿'},
      {id:'asset_laptop',orgId:'org_kampus',name:'Laptop Lenovo ThinkPad',code:'IT-008',category:'Elektronik',location:'Ruang Sekretariat',condition:'Baik',status:'borrowed',qty:1,description:'Laptop untuk kegiatan akademik dan acara.',icon:'💻'},
      {id:'asset_projector',orgId:'org_komunitas',name:'Proyektor Epson',code:'AV-002',category:'Audio Visual',location:'Gudang Utama',condition:'Baik',status:'available',qty:1,description:'Proyektor untuk rapat, pelatihan, dan presentasi.',icon:'📽️'},
      {id:'asset_speaker',orgId:'org_komunitas',name:'Speaker Portable',code:'AV-005',category:'Audio Visual',location:'Gudang Utama',condition:'Perlu perawatan',status:'maintenance',qty:1,description:'Speaker portable untuk acara komunitas.',icon:'🔊'}
    ],borrowings:[{id:'brw_01',orgId:'org_kampus',assetId:'asset_laptop',userId:'user_demo',borrower:'Kirana Ayu',purpose:'Presentasi kegiatan jurusan',borrowDate:date(-2),dueDate:date(4),status:'BORROWED',quantity:1},{id:'brw_02',orgId:'org_komunitas',assetId:'asset_projector',userId:'user_demo',borrower:'Kirana Ayu',purpose:'Workshop desain',borrowDate:date(1),dueDate:date(3),status:'PENDING',quantity:1}],damageReports:[{id:'dmg_01',orgId:'org_komunitas',assetId:'asset_speaker',reporter:'Kirana Ayu',description:'Suara speaker kadang terputus.',severity:'Sedang',status:'OPEN',createdAt:date(-1)}],maintenance:[{id:'mnt_01',orgId:'org_komunitas',assetId:'asset_speaker',type:'Pemeriksaan audio',description:'Periksa kabel dan konektor speaker.',scheduledAt:date(2),status:'SCHEDULED'}],categories:[{id:'cat_1',orgId:'org_komunitas',name:'Audio Visual',description:'Proyektor, speaker, perangkat presentasi'},{id:'cat_2',orgId:'org_komunitas',name:'Peralatan Acara',description:'Perlengkapan kegiatan'},{id:'cat_3',orgId:'org_foto',name:'Kamera',description:'Kamera dan lensa'}],locations:[{id:'loc_1',orgId:'org_komunitas',name:'Gudang Utama',description:'Penyimpanan perlengkapan acara'},{id:'loc_2',orgId:'org_kampus',name:'Ruang Sekretariat',description:'Ruang penyimpanan jurusan'}],notifications:[{id:'nt_1',userId:'user_demo',title:'Selamat datang di OrgInventory',message:'Lengkapi profil dan kelola ruangmu.',createdAt:new Date().toISOString(),read:false}],invitations:[]};
    localStorage.setItem(DBKEY,JSON.stringify(demo)); return demo;
  };
  let db; try { db=JSON.parse(localStorage.getItem(DBKEY)||'null')||seed(); } catch(e) { db=seed(); }
  if (autoDemo && db.users.some(u=>u.id==='user_demo')) { db.session='user_demo'; localStorage.setItem(DBKEY,JSON.stringify(db)); }
  const save=()=>localStorage.setItem(DBKEY,JSON.stringify(db));
  const currentUser=()=>db.users.find(u=>u.id===db.session)||null;
  const orgById=id=>db.orgs.find(o=>o.id===id);
  const activeOrg=()=>currentUser()?((orgById(db.activeOrg)&&membership(db.activeOrg))?orgById(db.activeOrg):(userOrgs()[0]||null)):null;
  const membership=(orgId,userId=currentUser()?.id)=>db.memberships.find(m=>m.orgId===orgId&&m.userId===userId&&m.status==='active');
  const userOrgs=()=>currentUser()?db.orgs.filter(o=>membership(o.id)):[];
  const orgAssets=(orgId=activeOrg()?.id)=>db.assets.filter(a=>a.orgId===orgId&&!a.deleted);
  const orgBorrowings=(orgId=activeOrg()?.id)=>db.borrowings.filter(b=>b.orgId===orgId);
  const assetById=id=>db.assets.find(a=>a.id===id);
  const borrowingById=id=>db.borrowings.find(b=>b.id===id);
  const myBorrowings=()=>db.borrowings.filter(b=>b.userId===currentUser()?.id);
  const url=(p,params={})=>p+(Object.keys(params).length?'?'+new URLSearchParams(params):'');
  const toast=msg=>{let el=$('.toast');if(!el){el=document.createElement('div');el.className='toast';document.body.appendChild(el);}el.textContent=msg;el.classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.add('hidden'),3300);};
  const requireAuth=()=>{if(!currentUser()){location.href=url('login.html',{next:location.pathname.split('/').pop()+(location.search||'')});return false;}return true;};
  const requireOrg=()=>{if(!activeOrg()){location.href='my-organizations.html';return false;}return true;};
  const currentRole=()=>membership(activeOrg()?.id)?.role||'NONE';
  const canManage=()=>['ADMIN','STAFF'].includes(currentRole());
  const requireRole=roles=>{if(!requireAuth())return false;if(!requireOrg())return false;if(!roles.includes(currentRole())){toast('Peran akunmu tidak memiliki izin untuk halaman ini.');location.href='organization-dashboard.html';return false;}return true;};
  const iconFor=page=>({'user-dashboard':'⌂','organization-dashboard':'▦','inventory':'▣','asset-form':'+','borrowings':'⇄','borrowing-detail':'↗','damage-reports':'⚠','maintenance':'⚙','categories':'▤','locations':'⌖','members':'♧','reports':'▥','settings':'⚙','my-borrowings':'⇄','notifications':'♢','profile':'◉','my-organizations':'▦','create-organization':'+'})[page]||'•';
  const link=(p,label,ico=iconFor(p),active=false)=>currentRole()==='STAFF'&&['members','reports','settings','audit'].includes(p)?`<span class="side-link" aria-disabled="true" style="opacity:.45">${label} · Admin</span>`:`<a class="side-link ${active?'active':''}" href="${p}.html"><span class="ico">${ico}</span>${label}</a>`;
  const orgSidebar=()=>`<div class="side-org"><div class="org-avatar">${safe(initials(activeOrg()?.name))}</div><div style="min-width:0"><b style="display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis">${safe(activeOrg()?.name||'Pilih ruang inventaris')}</b><span class="muted small">${safe(membership(activeOrg()?.id)?.role||'Workspace')}</span></div></div><div><div class="side-label">WORKSPACE</div>${link('organization-dashboard','Dashboard','▦',page==='organization-dashboard')}${link('inventory','Inventory','▣',page==='inventory'||page==='asset-form')}${link('borrowings','Peminjaman','⇄',page==='borrowings'||page==='borrowing-detail')}${link('damage-reports','Laporan Kerusakan','⚠',page==='damage-reports')}${link('maintenance','Maintenance','⚙',page==='maintenance')}${link('charges','Tagihan & Pembayaran','▤',page==='charges'||page==='charge-detail')}${link('audit','Audit Aktivitas','◷',page==='audit')}</div><div><div class="side-label">PENGELOLAAN</div>${link('categories','Kategori','▤',page==='categories')}${link('locations','Lokasi','⌖',page==='locations')}${link('members','Anggota','♧',page==='members')}${link('reports','Laporan','▥',page==='reports')}${link('settings','Pengaturan','⚙',page==='settings')}</div><div><div class="side-label">AKUN</div>${link('my-organizations','Ruang Saya','▦')}${link('user-dashboard','Beranda pengguna','⌂')}${link('index','Lihat halaman publik','↗')}</div>`;
  const userSidebar=()=>`<div class="side-org"><div class="org-avatar">${safe(initials(currentUser()?.name))}</div><div><b style="display:block;font-size:12px">${safe(currentUser()?.name||'Pengguna')}</b><span class="muted small">Akun pengguna</span></div></div><div><div class="side-label">MENU PENGGUNA</div>${link('user-dashboard','Beranda','⌂',page==='user-dashboard')}${link('my-organizations','Ruang Saya','▦',page==='my-organizations')}${link('create-organization','Buat Ruang Inventaris','+',page==='create-organization')}${link('my-borrowings','Peminjamanku','⇄',page==='my-borrowings')}${link('my-charges','Tagihan Saya','▤',page==='my-charges')}${link('scan-qr','Scan QR','▣',page==='scan-qr')}${link('notifications','Notifikasi','♢',page==='notifications')}${link('profile','Profil','◉',page==='profile')}</div><div><div class="side-label">RUANG SAYA</div>${userOrgs().map(o=>`<a href="#" class="side-link ${o.id===db.activeOrg?'active':''}" data-action="switch-org" data-id="${o.id}"><span class="org-avatar" style="width:26px;height:26px;border-radius:8px;font-size:10px">${safe(initials(o.name))}</span><span style="overflow:hidden;text-overflow:ellipsis">${safe(o.name)}</span></a>`).join('')}</div>`;
  const shell=(content,{workspace=false,userArea=false}={})=>{
    const user=currentUser();
    const top=`<header class="topbar"><div class="wrap topbar-inner"><a href="index.html" class="brand"><span class="brand-mark">O</span><span>OrgInventory</span></a><nav class="nav"><a href="index.html" class="${page==='home'?'active':''}">Beranda</a><a href="organizations.html" class="${['organizations','organization-detail','asset-public'].includes(page)?'active':''}">Jelajahi Ruang</a>${user?'<a href="user-dashboard.html">Dashboard</a>':''}</nav><div class="top-actions">${user?`<button class="btn secondary sm hide-mobile" data-action="logout">Keluar</button><a href="profile.html" class="org-avatar" style="width:34px;height:34px;font-size:12px">${safe(initials(user.name))}</a>`:`<a class="btn ghost hide-mobile" href="login.html">Masuk</a><a class="btn" href="register.html">Daftar</a>`}${(workspace||userArea)?'<button class="btn secondary sm mobile-toggle" data-action="toggle-sidebar" aria-label="Buka menu">☰</button>':''}</div></div></header>`;
    const sidebar=workspace?`<aside class="sidebar" id="sidebar">${orgSidebar()}</aside>`:userArea?`<aside class="sidebar" id="sidebar">${userSidebar()}</aside>`:'';
    if(workspace||userArea)return `${top}<div class="app-layout">${sidebar}<main class="main">${content}</main></div><div id="toastRoot"></div>`;
    return `${top}${content}`;
  };
  const head=(title,desc,actions='')=>`<div class="page-head"><div><h1>${title}</h1><p>${desc||''}</p></div>${actions?`<div class="head-actions">${actions}</div>`:''}</div>`;
  const btn=(text,href,cl='btn')=>`<a class="${cl}" href="${href}">${text}</a>`;
  const stat=(label,note,num,ico='▦')=>`<div class="stat-card"><div class="stat-top"><span>${label}</span><span class="stat-ico">${ico}</span></div><div class="stat-number">${num}</div><div class="stat-note">${note}</div></div>`;
  const statusTag=s=>{const cl=({available:'green',PENDING:'amber',BORROWED:'blue',APPROVED:'blue',RETURNED:'green',REJECTED:'red',maintenance:'amber',OPEN:'red',IN_PROGRESS:'blue',RESOLVED:'green',SCHEDULED:'blue',COMPLETED:'green',OVERDUE:'red'})[s]||'';const names={available:'Tersedia',maintenance:'Maintenance',PENDING:'Menunggu',BORROWED:'Dipinjam',APPROVED:'Disetujui',RETURNED:'Dikembalikan',REJECTED:'Ditolak',OPEN:'Terbuka',IN_PROGRESS:'Diproses',RESOLVED:'Selesai',SCHEDULED:'Terjadwal',COMPLETED:'Selesai',OVERDUE:'Terlambat'};return `<span class="tag ${cl}">${names[s]||safe(s)}</span>`;};
  const empty=(title,desc,cta='')=>`<div class="empty"><div class="empty-icon">◎</div><h3>${title}</h3><p>${desc}</p>${cta}</div>`;
  const orgCard=o=>{const assets=membership(o.id)?db.assets.filter(a=>a.orgId===o.id):[].length;return `<article class="card hover"><div class="org-row"><div class="org-avatar">${safe(initials(o.name))}</div><div style="min-width:0;flex:1"><div style="display:flex;justify-content:space-between;gap:8px;align-items:flex-start"><h3>${safe(o.name)}</h3>${o.visibility==='public'?'<span class="tag green">Publik</span>':'<span class="tag">Privat</span>'}</div><p>⌖ ${safe(o.location||'Lokasi belum diatur')}</p></div></div><p class="muted" style="margin:17px 0 0;font-size:12px">${safe(o.description||'Belum ada deskripsi ruang inventaris.')}</p><div class="card-foot"><span class="muted small">▣ ${assets} aset</span>${btn('Lihat ruang inventaris ↗',url('organization-detail.html',{id:o.id}),'btn secondary sm')}</div></article>`;};
  const assetCard=a=>{const org=orgById(a.orgId);return `<article class="card hover"><div class="asset-cover" style="height:130px;font-size:50px">${safe(a.icon||'📦')}</div><div style="display:flex;justify-content:space-between;gap:8px;margin-top:16px;align-items:flex-start"><div><h3 style="font-size:15px;margin:0">${safe(a.name)}</h3><div class="muted small" style="margin-top:3px">${safe(a.code)} · ${safe(a.category)}</div></div>${statusTag(a.status)}</div><p class="muted small" style="margin:11px 0">${safe(org?.name||'Ruang Inventaris')} · ${safe(a.location||'Lokasi belum diatur')}</p><div class="card-foot"><span class="small muted">Jumlah: 1</span>${btn('Detail aset',url('asset-public.html',{id:a.id}),'btn secondary sm')}</div></article>`;};
