  function renderInspection(){if(!requireRole(['ADMIN','STAFF']))return '';const b=borrowingById(new URLSearchParams(location.search).get('id'));if(!b||b.orgId!==activeOrg().id||!['BORROWED','OVERDUE'].includes(b.status))return shell(empty('Tidak ada pengembalian aktif','Pilih transaksi Borrowed atau Overdue dari daftar peminjaman.',btn('Peminjaman','borrowings.html')),{workspace:true});const days=Math.max(0,Math.round((new Date(date()).getTime()-new Date(b.dueDate).getTime())/86400000)),fine=days*(b.lateRateSnapshot||5000);return shell(`${head('Inspeksi Pengembalian',`${safe(b.borrower)} · ${safe(assetById(b.assetId)?.name)}`,btn('← Kembali',url('borrowing-detail.html',{id:b.id}),'btn secondary'))}<div class="detail-grid"><div class="panel"><div class="panel-head"><h2>Catat kondisi akhir</h2></div><div class="panel-body"><form data-form="inspection" data-id="${b.id}"><div class="field"><label>Hasil inspeksi</label><select class="select" name="condition"><option>Baik</option><option>Rusak ringan</option><option>Rusak berat</option><option>Hilang</option></select></div>${inputField('Catatan pemeriksaan','notes')}${inputField('Referensi bukti pemeriksaan','evidence')}<div class="notice info">Baik/rusak ringan → Available. Rusak berat → Maintenance. Hilang → Lost. Kerusakan tidak otomatis menjadi tagihan.</div>${inputField('Denda akhir (Rp)','fine','number',`min="0" value="${fine}"`)}<div class="field"><label>Alasan penyesuaian denda (wajib bila berubah)</label><textarea class="textarea" name="fineReason"></textarea></div><button class="btn" type="submit">Tinjau & selesaikan pengembalian</button></form></div></div><div class="panel"><div class="panel-head"><h2>Perhitungan keterlambatan</h2></div><div class="panel-body"><p>${days} hari × ${rupiah(b.lateRateSnapshot||5000)}</p><h2>${rupiah(fine)}</h2><p class="muted small">Tarif memakai snapshot saat approval. Tagihan late fee hanya diterbitkan jika nilai akhir positif.</p><p class="notice info">Pengembalian selesai terlepas dari status pembayaran.</p></div></div></div>`,{workspace:true});}
  function handleFinanceAction(act,id,el){
    if(act==='export-finance'){if(currentRole()!=='ADMIN')return true;const rows=[['Tagihan','Jenis','Nominal','Dibayar confirmed','Pembebasan','Sisa','Status'],...db.charges.filter(c=>c.orgId===activeOrg().id).map(c=>{const t=chargeTotals(c);return[c.id,c.type,c.amount,t.paid,t.credit,c.status==='issued'?t.balance:0,t.state]})];const csv=rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\n');const a=window.document.createElement('a');const u=URL.createObjectURL(new Blob(['\ufeff'+csv],{type:'text/csv'}));a.href=u;a.download='tagihan-pembayaran.csv';a.click();URL.revokeObjectURL(u);return true;}
    if(act==='join-space'){if(!requireAuth())return true;if(db.joinRequests.some(r=>r.orgId===id&&r.userId===currentUser().id&&r.status==='PENDING'))return true;db.joinRequests.push({id:uid('join'),orgId:id,userId:currentUser().id,status:'PENDING'});save();location.reload();return true;}
    if(['accept-join','reject-join'].includes(act)){const r=db.joinRequests.find(r=>r.id===id);if(!r||currentRole()!=='ADMIN'||r.orgId!==activeOrg().id)return true;r.status=act==='accept-join'?'APPROVED':'REJECTED';if(r.status==='APPROVED'){const m=db.memberships.find(m=>m.orgId===r.orgId&&m.userId===r.userId);if(m)m.status='active';else db.memberships.push({id:uid('mem'),orgId:r.orgId,userId:r.userId,role:'MEMBER',status:'active'});}save();location.reload();return true;}
    if(act==='cancel-borrow'){const b=borrowingById(id);if(b?.userId===currentUser()?.id&&b.status==='PENDING'&&confirm('Batalkan permintaan ini?')){b.status='CANCELLED';save();location.reload();}return true;}
    if(!['issue-charge','cancel-charge','confirm-payment','reject-payment','void-payment'].includes(act))return false;
    const p=db.payments.find(p=>p.id===id),c=db.charges.find(c=>c.id===(p?p.chargeId:id));if(!c||!financeAdmin(c)){toast('Tindakan memerlukan Admin ruang selain peminjam.');return true;}const t=chargeTotals(c);
    if(act==='issue-charge'){const b=borrowingById(c.borrowingId);if(c.status!=='draft')return true;if(!b?.policySnapshot||!c.reason||!c.evidence||c.amount<=0){toast('Lengkapi kebijakan yang disetujui, bukti, dan penilaian.');return true;}if(!confirm(`Terbitkan tagihan ${rupiah(c.amount)} kepada ${b.borrower}?`))return true;c.status='issued';c.issuedAt=date();financeLog('Tagihan diterbitkan',c,c.reason);}
    if(act==='cancel-charge'){if(c.status!=='issued'||t.paid||t.credit){toast('Tagihan sudah memiliki pembayaran atau pembebasan.');return true;}const reason=prompt('Alasan pembatalan tagihan');if(!reason?.trim())return true;c.status='cancelled';db.payments.filter(p=>p.chargeId===c.id&&p.status==='pending').forEach(p=>{p.status='rejected';p.reason='Tagihan dibatalkan';});financeLog('Tagihan dibatalkan',c,reason);}
    if(act==='confirm-payment'){if(!p||p.status!=='pending'||c.status!=='issued')return true;if(p.amount>t.balance){toast('Pembayaran melebihi sisa terbaru. Tolak dan catat nominal yang benar.');return true;}if(!confirm(`Konfirmasi penerimaan ${rupiah(p.amount)}?`))return true;p.status='confirmed';p.confirmedBy=currentUser().id;p.confirmedAt=new Date().toISOString();financeLog('Pembayaran dikonfirmasi',c,`${rupiah(p.amount)} · ${p.reference}`);}
    if(act==='reject-payment'||act==='void-payment'){if(!p||p.status!==(act==='reject-payment'?'pending':'confirmed'))return true;const reason=prompt(act==='void-payment'?'Alasan void (riwayat tetap disimpan)':'Alasan menolak bukti pembayaran');if(!reason?.trim())return true;p.status=act==='void-payment'?'voided':'rejected';p.reason=reason;p.decidedBy=currentUser().id;financeLog(act==='void-payment'?'Pembayaran di-void':'Pembayaran ditolak',c,reason);}
    save();location.reload();return true;
  }
  function handleFinanceForm(kind,v,form){
    if(kind==='scan-code'){const a=db.assets.find(a=>a.code.toLowerCase()===String(v.code).trim().toLowerCase());if(!a)toast('Kode tidak ditemukan. Periksa kode lalu coba lagi.');else location.href=membership(a.orgId)?url('asset-public.html',{id:a.id}):url('organization-detail.html',{id:a.orgId});return true;}
    if(!['charge-draft','payment','credit','inspection'].includes(kind))return false;
    if(!canManage())return true;
    if(kind==='inspection'){const b=borrowingById(form.dataset.id);if(!b||b.orgId!==activeOrg().id||!['BORROWED','OVERDUE'].includes(b.status))return true;const days=Math.max(0,Math.round((new Date(date()).getTime()-new Date(b.dueDate).getTime())/86400000)),calc=days*(b.lateRateSnapshot||5000),fine=Number(v.fine);if(fine<0||!Number.isInteger(fine)||(fine!==calc&&!v.fineReason?.trim())){toast('Perubahan denda memerlukan alasan dan nominal valid.');return true;}if(!confirm('Selesaikan pengembalian dengan hasil inspeksi ini?'))return true;Object.assign(b,{status:'RETURNED',returnCondition:v.condition,returnNotes:v.notes,returnEvidence:v.evidence,returnedAt:date(),fine,calculatedFine:calc});const a=assetById(b.assetId);a.condition=v.condition;a.status=({'Baik':'available','Rusak ringan':'available','Rusak berat':'maintenance','Hilang':'lost'})[v.condition];if(v.condition!=='Baik')db.damageReports.push({id:uid('dmg'),orgId:b.orgId,assetId:b.assetId,borrowingId:b.id,reporter:currentUser().name,description:v.notes,severity:v.condition,status:'OPEN',evidence:v.evidence,createdAt:date()});if(fine>0)db.charges.push({id:uid('chg'),orgId:b.orgId,borrowingId:b.id,userId:b.userId,type:'late_fee',amount:fine,status:'issued',issuedAt:date(),reason:`${days} hari × ${rupiah(b.lateRateSnapshot||5000)}. ${v.fineReason||''}`});save();location.href='charges.html';return true;}
    if(kind==='charge-draft'){const b=borrowingById(v.borrowingId);if(!b||b.orgId!==activeOrg()?.id||b.status!=='RETURNED'||!b.returnCondition||b.returnCondition==='Baik'){toast('Pilih transaksi dengan hasil inspeksi kerusakan/kehilangan.');return true;}if(db.charges.some(c=>c.borrowingId===b.id&&['damage','loss'].includes(c.type)&&c.status!=='cancelled')){toast('Sudah ada draft/tagihan kerusakan atau penggantian untuk kejadian ini.');return true;}if((v.type==='loss')!==(b.returnCondition==='Hilang')){toast('Jenis tagihan harus sesuai hasil inspeksi.');return true;}const amount=Number(v.amount);if(!Number.isInteger(amount)||amount<=0)return true;const c={id:uid('chg'),orgId:b.orgId,borrowingId:b.id,userId:b.userId,type:v.type,amount,status:'draft',reason:v.reason,evidence:v.evidence,createdAt:date()};db.charges.push(c);financeLog('Draft penilaian dibuat',c,v.reason);save();location.href=url('charge-detail.html',{id:c.id});return true;}
    const c=db.charges.find(c=>c.id===form.dataset.id);if(!c||c.orgId!==activeOrg().id||c.status!=='issued')return true;const amount=Number(v.amount),t=chargeTotals(c);if(!Number.isInteger(amount)||amount<=0||amount>t.balance){toast('Nominal harus positif dan tidak melebihi sisa.');return true;}
    if(kind==='payment'){if(v.paidAt<c.issuedAt||v.paidAt>date()||!v.reference?.trim()){toast('Periksa tanggal dan bukti penerimaan.');return true;}db.payments.push({id:uid('pay'),chargeId:c.id,amount,status:'pending',paidAt:v.paidAt,method:v.method,reference:v.reference,createdBy:currentUser().id});financeLog('Pembayaran dicatat pending',c,`${rupiah(amount)} · ${v.reference}`);}
    if(kind==='credit'){if(!financeAdmin(c)){toast('Pembebasan memerlukan Admin selain peminjam.');return true;}if(!confirm(`Bebaskan ${rupiah(amount)} dengan alasan: ${v.reason}?`))return true;db.credits.push({id:uid('credit'),chargeId:c.id,amount,reason:v.reason,actor:currentUser().name});financeLog('Pembebasan saldo',c,v.reason);}
    save();location.reload();return true;
  }

