  // Public organization search is rendered separately so filters work without rerendering app shell.
  function refreshOrgResults(){if(!$('#orgResults'))return;const q=($('#orgSearch')?.value||'').toLowerCase().trim(),vis=$('#orgVisibility')?.value||'all';const list=db.orgs.filter(o=>o.visibility==='public'&&[o.name,o.location,o.description].join(' ').toLowerCase().includes(q));$('#orgResults').innerHTML=list.map(orgCard).join('')||empty('Ruang Inventaris tidak ditemukan','Coba kata kunci atau filter lainnya.');$('#orgCount').textContent=`${list.length} ruang inventaris`;}
  $('#financeFilter')?.addEventListener('change',e=>{const cs=db.charges.filter(c=>page==='my-charges'?c.userId===currentUser().id:c.orgId===activeOrg()?.id);$('#financeRows').innerHTML=chargeRows(cs.filter(c=>e.target.value==='all'||chargeTotals(c).state===e.target.value));});
